//! CLI seam: schema discovery, write-mode, check-mode. All IO lives here so
//! `emit.rs` stays pure; `main.rs` and integration tests share this module.

use std::{
    collections::HashSet,
    io::{BufRead, BufReader},
    path::{Path, PathBuf},
};

use thiserror::Error;

use crate::{
    emit::GeneratedFile,
    schema::{SchemaError, SchemaFile},
};

/// first line every generated file starts with (see `emit::provenance_header`).
const GENERATED_MARKER: &str = "//! GENERATED by proto-codegen";

/// repo root two directories up from this crate (`crates/codegen/../..`).
pub fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .expect("repo root must exist on disk")
}

/// `path` relative to `root` with `/` separators on every host: the provenance
/// header records it, so the committed output must not depend on the OS.
pub fn schema_rel_path(root: &Path, path: &Path) -> String {
    path.strip_prefix(root)
        .unwrap_or(path)
        .to_string_lossy()
        .replace(std::path::MAIN_SEPARATOR, "/")
}

/// recursively collect every `.yaml` file under `dir`, sorted for deterministic ordering.
/// a missing or unreadable `dir` yields an empty list (fresh repo with no schemas is legal).
///
/// `<dir>/records` is excluded: normalized-record schemas live there and use a distinct
/// DSL (`record_schema`), not the venue-wire `SchemaFile`. Their own discovery is
/// `discover_record_schema_paths`. Without this skip the wire pass would try to load a
/// record schema and fail on the absent `venue`/`endianness` keys.
pub fn discover_schema_paths(dir: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    walk_yaml(dir, &mut out);
    let records_dir = dir.join("records");
    out.retain(|p| !p.starts_with(&records_dir));
    out.sort();
    out
}

fn walk_yaml(dir: &Path, out: &mut Vec<PathBuf>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            walk_yaml(&path, out);
        } else if path.extension().is_some_and(|e| e == "yaml") {
            out.push(path);
        }
    }
}

/// collect every `.yaml` under `dir` (the `schemas/records/` subtree), sorted. Companion
/// to `discover_schema_paths`, which excludes that subtree: these feed the normalized
/// record generator (`record_emit`), a distinct DSL from the venue-wire `SchemaFile`.
pub fn discover_record_schema_paths(dir: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    walk_yaml(dir, &mut out);
    out.sort();
    out
}

/// this repo's layout rule: a schema's venue crate lives at `crates/venues/<venue>`, e.g.
/// `crates/venues/nasdaq`. The binary and drift gate pass it to `emit::generate`; a repo
/// with another layout passes its own directory instead.
pub fn venue_crate_dir(s: &SchemaFile) -> PathBuf {
    PathBuf::from("crates/venues").join(&s.venue)
}

/// ensure the schema's venue crate directory exists under `repo_root`. write mode refuses
/// to create a new venue crate implicitly: bootstrapping one is a hand step.
pub fn ensure_venue_crate_exists(repo_root: &Path, s: &SchemaFile) -> Result<(), SchemaError> {
    let dir = venue_crate_dir(s);
    if repo_root.join(&dir).is_dir() {
        Ok(())
    } else {
        Err(SchemaError::MissingVenueCrate { dir })
    }
}

/// write every generated file under `repo_root`, creating parent directories as needed.
pub fn write_outputs(repo_root: &Path, files: &[GeneratedFile]) -> std::io::Result<()> {
    for f in files {
        let full = repo_root.join(&f.rel_path);
        if let Some(parent) = full.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(&full, &f.contents)?;
    }
    Ok(())
}

/// compare generated files against what is on disk under `repo_root`. returns every
/// rel_path that is missing or byte-different; empty means fully fresh.
pub fn check_outputs(repo_root: &Path, files: &[GeneratedFile]) -> Vec<PathBuf> {
    let mut drifted = Vec::new();
    for f in files {
        let full = repo_root.join(&f.rel_path);
        match std::fs::read(&full) {
            Ok(disk) if disk == f.contents.as_bytes() => {}
            _ => drifted.push(f.rel_path.clone()),
        }
    }
    drifted
}

/// every `.rs` file under `repo_root/owned_dir` (recursive) whose repo-root-relative path
/// is not in `expected`. missing dir -> empty (pre-generation is legal). sorted for
/// deterministic ordering. non-`.rs` files ignored. symlinks never followed or reported.
pub fn find_orphans(
    repo_root: &Path,
    owned_dir: &Path,
    expected: &[GeneratedFile],
) -> Vec<PathBuf> {
    let expected_set: HashSet<&Path> = expected.iter().map(|f| f.rel_path.as_path()).collect();
    let mut orphans = Vec::new();
    walk_orphans(
        repo_root,
        &repo_root.join(owned_dir),
        &expected_set,
        &mut orphans,
    );
    orphans.sort();
    orphans
}

fn walk_orphans(repo_root: &Path, dir: &Path, expected: &HashSet<&Path>, out: &mut Vec<PathBuf>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        // file_type() reports the symlink type itself, not the target: a symlinked
        // dir or file is neither is_dir() nor is_file() here, so it is skipped.
        let Ok(file_type) = entry.file_type() else {
            continue;
        };
        let path = entry.path();
        if file_type.is_dir() {
            walk_orphans(repo_root, &path, expected, out);
        } else if file_type.is_file() && path.extension().is_some_and(|e| e == "rs") {
            let rel = path.strip_prefix(repo_root).unwrap_or(&path);
            if !expected.contains(rel) {
                out.push(rel.to_path_buf());
            }
        }
    }
}

/// delete orphans whose first line carries the GENERATED marker. two-pass: classify
/// every orphan before deleting any, so a mixed marked/foreign set deletes nothing.
pub fn prune_orphans(repo_root: &Path, orphans: &[PathBuf]) -> Result<Vec<PathBuf>, PruneError> {
    for rel in orphans {
        if !has_generated_marker(&repo_root.join(rel)) {
            return Err(PruneError::Foreign { path: rel.clone() });
        }
    }

    let mut deleted = Vec::with_capacity(orphans.len());
    for rel in orphans {
        std::fs::remove_file(repo_root.join(rel)).map_err(|source| PruneError::Io {
            path: rel.clone(),
            source,
        })?;
        deleted.push(rel.clone());
    }
    Ok(deleted)
}

/// true if `full`'s first line starts with the GENERATED marker. any open/read failure
/// (missing, permission denied, non-UTF8) reads as false: cannot prove it is generated.
fn has_generated_marker(full: &Path) -> bool {
    let Ok(file) = std::fs::File::open(full) else {
        return false;
    };
    let mut first_line = String::new();
    match BufReader::new(file).read_line(&mut first_line) {
        Ok(_) => first_line.starts_with(GENERATED_MARKER),
        Err(_) => false,
    }
}

/// write mode refuses to delete a stray file it cannot prove is generated output.
#[derive(Debug, Error)]
pub enum PruneError {
    #[error("refusing to delete non-generated file in generated tree: {}", .path.display())]
    Foreign { path: PathBuf },
    #[error("io error pruning {}: {source}", .path.display())]
    Io {
        path: PathBuf,
        source: std::io::Error,
    },
}
